/**
 * Returns a tailored workout plan for a given physique type
 * @summary Get personalized workout plan
 */
export const getGetWorkoutPlanUrl = (
  physiqueType: "athletic" | "skinny" | "overweight",
  params?: GetWorkoutPlanParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/workouts/${physiqueType}?${stringifiedParams}`
    : `/api/workouts/${physiqueType}`;
};

